def test_field_roundtrip(regs):
    regs.FREQ_REG.FREQ.write(0xdeadbeef)
    assert regs.FREQ_REG.FREQ.read() == 0xdeadbeef
    regs.FREQ_REG.FREQ.write(0)
    regs.PHASE_REG.PHASE.write(0xdeadbeef)
    assert regs.PHASE_REG.PHASE.read() == 0xdeadbeef
    regs.PHASE_REG.PHASE.write(0)
    regs.NSAMP_REG.NSAMP.write(0xffff)
    assert regs.NSAMP_REG.NSAMP.read() == 0xffff
    regs.NSAMP_REG.NSAMP.write(0)
    regs.OUTSEL_REG.OUTSEL.write(0x3)
    assert regs.OUTSEL_REG.OUTSEL.read() == 0x3
    regs.OUTSEL_REG.OUTSEL.write(0)
    regs.MODE_REG.MODE.write(0x1)
    assert regs.MODE_REG.MODE.read() == 0x1
    regs.MODE_REG.MODE.write(0)
    regs.WE_REG.WE.write(0x1)
    assert regs.WE_REG.WE.read() == 0x1
    regs.WE_REG.WE.write(0)


def test_register_independence(regs):
    regs.FREQ_REG.FREQ.write(0xabcd)
    regs.PHASE_REG.PHASE.write(0xabcd)
    regs.NSAMP_REG.NSAMP.write(0xffff)
    regs.OUTSEL_REG.OUTSEL.write(0x3)
    regs.MODE_REG.MODE.write(0x1)
    regs.WE_REG.WE.write(0x1)
    assert regs.FREQ_REG.FREQ.read() == 0xabcd
    assert regs.PHASE_REG.PHASE.read() == 0xabcd
    assert regs.NSAMP_REG.NSAMP.read() == 0xffff
    assert regs.OUTSEL_REG.OUTSEL.read() == 0x3
    assert regs.MODE_REG.MODE.read() == 0x1
    assert regs.WE_REG.WE.read() == 0x1
